=== submission_08.ino ===
   1| // Lab 3 - Hardware PWM, D5, 1 kHz, 25%
   2| //
   3| // D5 = P1.13
   4| // PWM clock 16 MHz, DIV_16 -> 1 MHz
   5| // COUNTERTOP = 1000 (1 ms period)
   6| // compare = 250 (0.25 ms high)
   7| //
   8| // Prints the register values on startup so I can check them.
   9| 
  10| #include <Arduino.h>
  11| 
  12| #define PWM_TOP   1000
  13| #define PWM_CMP   250
  14| 
  15| static uint16_t seq0[1] = { PWM_CMP | 0x8000 };
  16| 
  17| void setup() {
  18|   Serial.begin(115200);
  19|   while (!Serial) { }
  20| 
  21|   NRF_PWM0->PSEL.OUT[0] = (1 << PWM_PSEL_OUT_PORT_Pos) | (13 << PWM_PSEL_OUT_PIN_Pos);
  22|   NRF_PWM0->ENABLE      = PWM_ENABLE_ENABLE_Enabled << PWM_ENABLE_ENABLE_Pos;
  23|   NRF_PWM0->MODE        = PWM_MODE_UPDOWN_Up << PWM_MODE_UPDOWN_Pos;
  24|   NRF_PWM0->PRESCALER   = PWM_PRESCALER_PRESCALER_DIV_16 << PWM_PRESCALER_PRESCALER_Pos;
  25|   NRF_PWM0->COUNTERTOP  = PWM_TOP;
  26|   NRF_PWM0->LOOP        = 0;
  27|   NRF_PWM0->DECODER     = (PWM_DECODER_LOAD_Common << PWM_DECODER_LOAD_Pos) |
  28|                           (PWM_DECODER_MODE_RefreshCount << PWM_DECODER_MODE_Pos);
  29|   NRF_PWM0->SEQ[0].PTR      = (uint32_t)seq0;
  30|   NRF_PWM0->SEQ[0].CNT      = 1;
  31|   NRF_PWM0->SEQ[0].REFRESH  = 0;
  32|   NRF_PWM0->SEQ[0].ENDDELAY = 0;
  33|   NRF_PWM0->TASKS_SEQSTART[0] = 1;
  34| 
  35|   Serial.print("COUNTERTOP = ");
  36|   Serial.println(NRF_PWM0->COUNTERTOP);
  37|   Serial.print("PRESCALER  = ");
  38|   Serial.println(NRF_PWM0->PRESCALER);
  39|   Serial.print("SEQ0       = 0x");
  40|   Serial.println(seq0[0], HEX);
  41| }
  42| 
  43| void loop() {
  44| }
</student_code>
